    procedure Lemma_Root_Represents_Key (H : Heap) is
@@
       pragma Assert (Key_At (H, Node) = H.Keys (Root_Position (H)));
    end Lemma_Root_Represents_Key;
+
+   procedure Lemma_Max_Parent_Beats_Child
+     (H : Heap; Parent : Index; Child : Tree_Index)
+     with Ghost,
+          Pre  => Parent < H.Capacity
+                  and then Child in 2 * Parent .. 2 * Parent + 1
+                  and then Max_Position_At (H, Child) > 0
+                  and then Node_Valid (H, Parent),
+          Post => Max_Position_At (H, Parent) > 0
+                  and then Max_Key_At (H, Parent) >= Max_Key_At (H, Child);
+
+   procedure Lemma_Max_Parent_Beats_Child
+     (H : Heap; Parent : Index; Child : Tree_Index) is null;
+
+   procedure Lemma_Root_Is_Maximum (H : Heap)
+     with Ghost,
+          Pre  => not Is_Empty (H) and then Is_Heap (H),
+          Post => Max_Position_At (H, 1) > 0
+                  and then Is_Maximum
+                    (H, (if H.Capacity = 1
+                         then H.Keys (1)
+                         else H.Max_Keys (1)));
+
+   procedure Lemma_Root_Is_Maximum (H : Heap) is
+      Node : Tree_Index;
+   begin
+      for I in 1 .. H.Last loop
+         Node := Leaf_Node (H, I);
+
+         while Node > 1 loop
+            Lemma_Heap_Node (H, Node / 2);
+            Lemma_Max_Parent_Beats_Child (H, Node / 2, Node);
+            Node := Node / 2;
+
+            pragma Loop_Invariant (Node <= 2 * H.Capacity - 1);
+            pragma Loop_Invariant (Max_Position_At (H, Node) > 0);
+            pragma Loop_Invariant (Max_Key_At (H, Node) >= H.Keys (I));
+            pragma Loop_Variant (Decreases => Node);
+         end loop;
+
+         pragma Loop_Invariant
+           (for all J in 1 .. I =>
+              (if H.Capacity = 1 then H.Keys (1) else H.Max_Keys (1))
+                >= H.Keys (J));
+      end loop;
+   end Lemma_Root_Is_Maximum;
+
+   procedure Lemma_Max_Root_Represents_Key (H : Heap)
+     with Ghost,
+          Pre  => not Is_Empty (H) and then Is_Heap (H),
+          Post => Max_Root_Position (H) in 1 .. H.Last
+                  and then
+                    (if H.Capacity = 1
+                     then H.Keys (1)
+                     else H.Max_Keys (1))
+                      = H.Keys (Max_Root_Position (H));
+
+   procedure Lemma_Max_Root_Represents_Key (H : Heap) is
+      Node : Tree_Index := 1;
+
+      procedure Lemma_Winner_Comes_From_Child (Parent : Index)
+        with Ghost,
+             Pre  => Parent < H.Capacity
+                     and then Max_Position_At (H, Parent) > 0
+                     and then Node_Valid (H, Parent),
+             Post =>
+               (Max_Position_At (H, 2 * Parent)
+                  = Max_Position_At (H, Parent)
+                and then Max_Position_At (H, 2 * Parent) > 0
+                and then Max_Key_At (H, 2 * Parent)
+                  = Max_Key_At (H, Parent))
+               or else
+               (Max_Position_At (H, 2 * Parent + 1)
+                  = Max_Position_At (H, Parent)
+                and then Max_Position_At (H, 2 * Parent + 1) > 0
+                and then Max_Key_At (H, 2 * Parent + 1)
+                  = Max_Key_At (H, Parent));
+
+      procedure Lemma_Winner_Comes_From_Child (Parent : Index) is null;
+   begin
+      Lemma_Root_Is_Maximum (H);
+
+      if H.Capacity = 1 then
+         return;
+      end if;
+
+      while Node < H.Capacity loop
+         declare
+            Left  : constant Tree_Index := 2 * Node;
+            Right : constant Tree_Index := Left + 1;
+         begin
+            pragma Assert (Max_Position_At (H, Node) > 0);
+            Lemma_Heap_Node (H, Node);
+            Lemma_Winner_Comes_From_Child (Node);
+            if Max_Position_At (H, Left) = Max_Position_At (H, Node)
+              and then Max_Position_At (H, Left) > 0
+              and then Max_Key_At (H, Left) = Max_Key_At (H, Node)
+            then
+               Node := Left;
+            else
+               pragma Assert
+                 (Max_Position_At (H, Right) = Max_Position_At (H, Node));
+               pragma Assert (Max_Position_At (H, Right) > 0);
+               pragma Assert
+                 (Max_Key_At (H, Right) = Max_Key_At (H, Node));
+               Node := Right;
+            end if;
+         end;
+
+         pragma Loop_Invariant
+           (Node <= 2 * H.Capacity - 1);
+         pragma Loop_Invariant
+           (Max_Position_At (H, Node) = H.Max_Winners (1));
+         pragma Loop_Invariant (Max_Position_At (H, Node) > 0);
+         pragma Loop_Invariant
+           (Max_Key_At (H, Node) = H.Max_Keys (1));
+         pragma Loop_Variant (Increases => Node);
+      end loop;
+
+      pragma Assert
+        (Max_Position_At (H, Node) = Node - H.Capacity + 1);
+      pragma Assert
+        (Max_Key_At (H, Node) = H.Keys (Max_Root_Position (H)));
+   end Lemma_Max_Root_Represents_Key;
@@
    function Peek_Min (H : Heap) return Key_Type is
@@
    end Peek_Min;
+
+   function Peek_Max (H : Heap) return Key_Type is
+   begin
+      Lemma_Root_Is_Maximum (H);
+      Lemma_Max_Root_Represents_Key (H);
+      return (if H.Capacity = 1 then H.Keys (1) else H.Max_Keys (1));
+   end Peek_Max;
@@
    function Min_Of (H : Heap) return Key_Type is
@@
    end Min_Of;
+
+   function Max_Of (H : Heap) return Key_Type is
+      Result : Key_Type := H.Keys (1);
+   begin
+      for I in 2 .. H.Last loop
+         if H.Keys (I) > Result then
+            Result := H.Keys (I);
+         end if;
+
+         pragma Loop_Invariant (for all J in 1 .. I => H.Keys (J) <= Result);
+         pragma Loop_Invariant
+           (for some J in 1 .. I => Result = H.Keys (J));
+      end loop;
+      return Result;
+   end Max_Of;
@@
    procedure Extract_Min (H : in out Heap; K : out Key_Type) is
@@
    end Extract_Min;
+
+   procedure Extract_Max (H : in out Heap; K : out Key_Type) is
+      Before : Heap := H with Ghost;
+      Keys_0 : constant Key_Array := H.Keys with Ghost;
+      Slot   : Index;
+      Last   : constant Index := H.Last;
+      Moved  : constant Key_Type := H.Keys (Last);
+      Leaf   : Tree_Index;
+   begin
+      Lemma_Root_Is_Maximum (H);
+      Lemma_Max_Root_Represents_Key (H);
+      Slot := Index (Max_Root_Position (H));
+      K := Peek_Max (H);
+
+      H.Keys (Slot) := Moved;
+      Leaf := Leaf_Node (H, Slot);
+      Lemma_Leaf_Changed (Before, H, Leaf);
+      Refresh_Path (H, Leaf);
+
+      Before := H;
+      H.Last := H.Last - 1;
+      Leaf := Leaf_Node (H, Last);
+      Lemma_Leaf_Changed (Before, H, Leaf);
+      Refresh_Path (H, Leaf);
+
+      if Slot < Last then
+         Models.Lemma_Set (Keys_0, H.Keys, Slot, Last - 1);
+         pragma Assert
+           (KM.Add (Models.Occurrences (H.Keys, Last - 1), K)
+            = KM.Add (Models.Occurrences (Keys_0, Last - 1), Moved));
+      else
+         Models.Lemma_Same_Prefix (Keys_0, H.Keys, Last - 1);
+      end if;
+   end Extract_Max;

 end Heaps.Min_Max_Tournament;

